class Solution {
public:
    int earliestAcq(vector<vector<int>>& logs, int n) {
        sort(logs.begin(), logs.end());
        vector<int> parent(n);
        iota(parent.begin(), parent.end(), 0);
        function<int(int)> find = [&](int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        };
        int components = n;
        for (const auto& log : logs) {
            int a = find(log[1]);
            int b = find(log[2]);
            if (a != b) {
                parent[a] = b;
                if (--components == 1) {
                    return log[0];
                }
            }
        }
        return -1;
    }
};
